// TestFieldIDString spot-checks the names a reading is logged under. Each
// expected string is the canonical header name the generator resolved for that
// id, which for a renamed field is the current spelling rather than the alias.
func TestFieldIDString(t *testing.T) {
	for _, c := range []struct {
		id   FieldID
		want string
	}{
		{FieldDevGpuTemp, "DCGM_FI_DEV_GPU_TEMP_CELSIUS"},
		{FieldDevPowerUsage, "DCGM_FI_DEV_BOARD_POWER_WATTS"},
		{FieldDevSmClock, "DCGM_FI_DEV_SM_CLOCK"},
		{FieldDevFbUsed, "DCGM_FI_DEV_FB_USED"},
	} {
		if got := c.id.String(); got != c.want {
			t.Errorf("FieldID(%d).String() = %q, want %q", uint16(c.id), got, c.want)
		}
	}
	if got := FieldID(0xffff).String(); got != "FieldID(65535)" {
		t.Errorf("an id with no name prints %q, want FieldID(65535)", got)
	}
}
